/**
 * The two constants check-published-artifacts.ts and the AGENTS.md generator
 * share. Kept apart from plugin-agents-md.ts so the publish gate does not
 * load prettier just to read a string.
 */
export const AGENTS_MD_MARKER =
  '<!-- Generated by scripts/generate-plugin-agents-md.ts from package.json and the plugin exports. Do not edit by hand; run `npm run agents-md`. -->';

/**
 * Plugins that do not get a generated consumer AGENTS.md. None: import-next was
 * excluded while another fixer owned it, and kept its hand-written contributor
 * file, whose `files` entry then shipped it and failed the published-artifact
 * gate (release run 44709499205: 4.1.2 never reached npm).
 */
export const AGENTS_MD_EXCLUDED = [] as const;
